  PROCEDURE report_check(
    p_label    IN VARCHAR2,
    p_expected IN NUMBER,
    p_actual   IN NUMBER
  ) IS
  BEGIN
    IF p_actual = p_expected THEN
      DBMS_OUTPUT.PUT_LINE(
        'PASS: ' || p_label ||
        '; expected=' || TO_CHAR(p_expected) ||
        ', actual=' || NVL(TO_CHAR(p_actual), 'NULL')
      );
    ELSE
      l_failure_count := l_failure_count + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: ' || p_label ||
        '; expected=' || TO_CHAR(p_expected) ||
        ', actual=' || NVL(TO_CHAR(p_actual), 'NULL')
      );
    END IF;
  END report_check;
BEGIN
  SAVEPOINT test_block_start;

  DBMS_OUTPUT.PUT_LINE('Testing HARNESS_APP.headcount');

  ---------------------------------------------------------------------------
  -- Check 1: a department_id that matches at least one row.
  ---------------------------------------------------------------------------
  BEGIN
    SELECT MIN(department_id)
      INTO l_matched_dept
      FROM HARNESS_APP.employees
     WHERE department_id IS NOT NULL;

    IF l_matched_dept IS NULL THEN
      l_failure_count := l_failure_count + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: matching department_id check; no non-NULL department_id row found to test'
      );
    ELSE
      SELECT COUNT(*)
        INTO l_expected
        FROM HARNESS_APP.employees
       WHERE department_id = l_matched_dept;

      BEGIN
        l_actual := HARNESS_APP.headcount(l_matched_dept);
      EXCEPTION
        WHEN OTHERS THEN
          l_actual := NULL;
      END;

      report_check(
        'matching department_id=' || TO_CHAR(l_matched_dept),
        l_expected,
        l_actual
      );
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      l_failure_count := l_failure_count + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: matching department_id check; setup failed: ' || SQLERRM
      );
  END;

  ---------------------------------------------------------------------------
  -- Check 2: a department_id that matches no row.
  -- Try 0 first if it is absent; otherwise derive a value above MAX(department_id).
  ---------------------------------------------------------------------------
  BEGIN
    SELECT COUNT(*)
      INTO l_expected
      FROM HARNESS_APP.employees
     WHERE department_id = 0;

    IF l_expected = 0 THEN
      l_nonmatch_dept := 0;
    ELSE
      SELECT MAX(department_id) + 1
        INTO l_nonmatch_dept
        FROM HARNESS_APP.employees
       WHERE department_id IS NOT NULL;

      IF l_nonmatch_dept IS NULL THEN
        l_failure_count := l_failure_count + 1;
        DBMS_OUTPUT.PUT_LINE(
          'FAIL: non-matching department_id check; no suitable value found to test'
        );
      ELSE
        SELECT COUNT(*)
          INTO l_expected
          FROM HARNESS_APP.employees
         WHERE department_id = l_nonmatch_dept;

        IF l_expected <> 0 THEN
          l_failure_count := l_failure_count + 1;
          DBMS_OUTPUT.PUT_LINE(
            'FAIL: non-matching department_id check; derived value ' ||
            TO_CHAR(l_nonmatch_dept) || ' unexpectedly matched ' ||
            TO_CHAR(l_expected) || ' row(s)'
          );
        ELSE
          BEGIN
            l_actual := HARNESS_APP.headcount(l_nonmatch_dept);
          EXCEPTION
            WHEN OTHERS THEN
              l_actual := NULL;
          END;

          report_check(
            'non-matching department_id=' || TO_CHAR(l_nonmatch_dept),
            0,
            l_actual
          );
        END IF;
      END IF;
    END IF;
  EXCEPTION
    WHEN OTHERS THEN
      l_failure_count := l_failure_count + 1;
      DBMS_OUTPUT.PUT_LINE(
        'FAIL: non-matching department_id check; setup failed: ' || SQLERRM
      );
  END;

  ---------------------------------------------------------------------------
  -- Check 3: NULL argument.
  -- headcount uses department_id = p_department_id, so NULL matches no rows.
  ---------------------------------------------------------------------------
  BEGIN
    l_actual := HARNESS_APP.headcount(NULL);
  EXCEPTION
    WHEN OTHERS THEN
      l_actual := NULL;
  END;

  report_check(
    'NULL department_id argument',
    0,
    l_actual
  );

  ROLLBACK TO test_block_start;

  IF l_failure_count <> 0 THEN
    RAISE_APPLICATION_ERROR(
      -20999,
      'headcount test block failed: ' || TO_CHAR(l_failure_count) || ' check(s) failed'
    );
  END IF;

EXCEPTION
  WHEN OTHERS THEN
    DBMS_OUTPUT.PUT_LINE('UNEXPECTED ERROR: ' || SQLERRM);
    ROLLBACK TO test_block_start;
    RAISE;
END;
```

The block tests three cases:

1. A `department_id` that matches at least one row in `HARNESS_APP.employees`, using the count from a separate query as the expected value.
2. A `department_id` that matches no row, first trying `0` if it is absent and otherwise using a value above `MAX(department_id)` and confirming with a separate count that it matches zero rows.
3. A `NULL` argument, where the expected result is `0` because the function compares `department_id = p_department_id`, and equality with `NULL` matches no rows.

Each check prints `PASS` or `FAIL` with expected and actual values, counts failures, and reports a failure if its setup cannot find anything to test. The block does not commit; it starts with `SAVEPOINT test_block_start`, rolls back to that savepoint at the end, and rolls back again before re-raising an unexpected error. I have not run this block.

